import { Component, Input } from '@angular/core';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';
import { GResponse } from '../../../../core/common/GResponse';
import { GAccount } from '../../../../core/common/GAccount';
import { combineLatest } from 'rxjs';
import { map } from 'rxjs/operators';

@Component({
  selector: 'app-page-header',
  templateUrl: './page-header.component.html',
  styleUrls: ['./page-header.component.scss']
})
export class PageHeaderComponent {
  @Input() titleKey = '';
  @Input() fallback = '/';
  @Input() defaultBack = true;
  readonly cartCount$ = combineLatest([
    GResponse.getCartCoursesCount(),
    GResponse.getCartProductsCount()
  ]).pipe(map(([courses, products]) => courses + products));

  get loggedIn(): boolean { return GAccount.IsLoggedIn(); }

  constructor(public language: SiteLanguageService) { }
}
